WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN amount >= 1390 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, order_id, PERCENTILE_APPROX(session_start_flag, 0.95) AS session_start_flag_p95, SIZE(COLLECT_SET(status)) AS num_status, COUNT(DISTINCT order_id) AS distinct_order_ids, MIN(prev_paid_at) AS first_prev_paid_at, COUNT(DISTINCT status) AS distinct_status, MAX(paid_at) AS last_seen, RANK() OVER (PARTITION BY CASE WHEN amount >= 1390 THEN 'LARGE' ELSE 'SMALL' END ORDER BY SIZE(COLLECT_SET(status)) DESC) AS num_status_rank FROM sessionized GROUP BY CASE WHEN amount >= 1390 THEN 'LARGE' ELSE 'SMALL' END, order_id ORDER BY distinct_order_ids DESC;
